CREATE TABLE metrics (id BIGINT NOT NULL, recorded_on DATE NOT NULL, reading DOUBLE PRECISION) PARTITION BY RANGE (recorded_on);
CREATE TABLE metrics_2026 PARTITION OF metrics FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');
ALTER TABLE metrics ADD COLUMN device TEXT;
CREATE SEQUENCE metric_numbers;
CREATE FUNCTION touch() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
CREATE OR REPLACE TRIGGER metrics_touch BEFORE UPDATE ON metrics FOR EACH ROW EXECUTE FUNCTION touch();
CREATE SCHEMA archive;
SET search_path TO archive;
CREATE TABLE snapshots (id BIGINT PRIMARY KEY, taken_at TIMESTAMPTZ NOT NULL);
